import openpyxl
wb = openpyxl.load_workbook('/root/output/result.xlsx')
ws = wb['Task']

print('=== Lookup block H12:L17 ===')
for r in range(12, 18):
    for c in range(8, 13):
        v = ws.cell(r,c).value
        print(f'  {ws.cell(r,c).coordinate}: {v}')

print('\n=== Flow block H35:L40 ===')
for r in range(35, 41):
    for c in range(8, 13):
        v = ws.cell(r,c).value
        print(f'  {ws.cell(r,c).coordinate}: {v}')

print('\n=== Stats H42:L47 ===')
for r in range(42, 48):
    for c in range(8, 13):
        v = ws.cell(r,c).value
        print(f'  {ws.cell(r,c).coordinate}: {v}')

print('\n=== Weighted mean H50:L50 ===')
for c in range(8, 13):
    v = ws.cell(50,c).value
    print(f'  {ws.cell(50,c).coordinate}: {v}')

# Verify none are None and all are formulas
bad = []

def check_range(r1,r2,c1,c2):
    for r in range(r1,r2+1):
        for c in range(c1,c2+1):
            v = ws.cell(r,c).value
            if v is None or not (isinstance(v,str) and v.startswith('=')):
                bad.append((r,c,v))

check_range(12,17,8,12)
check_range(19,24,8,12)
check_range(26,31,8,12)
check_range(35,40,8,12)
check_range(42,47,8,12)
check_range(50,50,8,12)

print('\n=== Formula presence check ===')
if bad:
    print('BAD CELLS:')
    for r,c,v in bad:
        print(f'  {ws.cell(r,c).coordinate}: {v!r}')
else:
    print('All target cells contain formula strings starting with =')

wb.close()
